"""Validate semantic version bumps against conventional commit history."""

from __future__ import annotations

import re
from enum import IntEnum

from pydantic import BaseModel


# Conventional commit pattern: type(scope)!: description
_COMMIT_PATTERN = re.compile(r"^(?P<type>\w+)(?:\([^)]*\))?(?P<bang>!)?\s*:\s*(?P<desc>.+)", re.DOTALL)


class BumpType(IntEnum):
    """Version bump severity. IntEnum enables natural comparison."""

    NONE = 0
    PATCH = 1
    MINOR = 2
    MAJOR = 3


# Map conventional commit types to bump levels
_BUMP_TYPES: dict[str, BumpType] = {
    "feat": BumpType.MINOR,
    "fix": BumpType.PATCH,
    "perf": BumpType.PATCH,
}


class BumpResult(BaseModel):
    """Result of bump validation."""

    valid: bool
    expected: BumpType
    proposed: BumpType
    reason: str
    suggestion: str | None = None


class BumpValidator:
    """Validate that a proposed version bump matches the commit history."""

    @staticmethod
    def classify_commit(message: str) -> BumpType:
        """Determine the bump type for a single commit message."""
        if "BREAKING CHANGE:" in message or "BREAKING-CHANGE:" in message:
            return BumpType.MAJOR

        match = _COMMIT_PATTERN.match(message)
        if not match:
            return BumpType.NONE

        if match.group("bang"):
            return BumpType.MAJOR

        commit_type = match.group("type").lower()
        return _BUMP_TYPES.get(commit_type, BumpType.NONE)

    @staticmethod
    def validate(commits: list[str], proposed_bump: BumpType) -> BumpResult:
        """Validate proposed bump against commit history."""
        if not commits:
            return BumpResult(
                valid=False,
                expected=BumpType.NONE,
                proposed=proposed_bump,
                reason="No commits to analyze",
                suggestion="Add commits before proposing a version bump.",
            )

        max_bump = BumpType.NONE
        for commit in commits:
            bump = BumpValidator.classify_commit(commit)
            if bump > max_bump:
                max_bump = bump

        if proposed_bump != max_bump:
            return BumpResult(
                valid=False,
                expected=max_bump,
                proposed=proposed_bump,
                reason=f"Commit history requires {max_bump.name} bump, but {proposed_bump.name} was proposed.",
                suggestion=f"Change version bump to {max_bump.name} based on commit analysis.",
            )

        return BumpResult(
            valid=True,
            expected=max_bump,
            proposed=proposed_bump,
            reason="Proposed bump matches commit history.",
        )

"""Version detection from git tags and pyproject.toml."""

from __future__ import annotations

import re
import subprocess
from pathlib import Path

from pydantic import BaseModel, field_validator


_TAG_PATTERN = re.compile(r"^v?(\d+)\.(\d+)\.(\d+)$")


def get_git_tags() -> list[str]:
    """Return all git tags from the repository."""
    result = subprocess.run(
        ["git", "tag", "--list"],
        capture_output=True,
        text=True,
        timeout=10,
    )
    return [t.strip() for t in result.stdout.splitlines() if t.strip()]


class VersionInfo(BaseModel):
    """Semantic version with validation."""

    major: int
    minor: int
    patch: int

    @field_validator("major", "minor", "patch")
    @classmethod
    def must_be_non_negative(cls, v: int) -> int:
        if v < 0:
            msg = "Version components must be non-negative"
            raise ValueError(msg)
        return v

    @classmethod
    def from_tag(cls, tag: str) -> VersionInfo:
        """Parse a git tag like 'v1.2.3' or '1.2.3'."""
        match = _TAG_PATTERN.match(tag.strip())
        if not match:
            msg = f"Invalid version tag: {tag!r}"
            raise ValueError(msg)
        return cls(major=int(match.group(1)), minor=int(match.group(2)), patch=int(match.group(3)))

    def as_tuple(self) -> tuple[int, int, int]:
        return (self.major, self.minor, self.patch)

    def __str__(self) -> str:
        return f"{self.major}.{self.minor}.{self.patch}"


class VersionDetector:
    """Detect the latest version from git tags or pyproject.toml."""

    def detect_latest(self) -> VersionInfo | None:
        """Return the highest semver tag, or None if no valid tags exist."""
        tags = get_git_tags()
        versions: list[VersionInfo] = []
        for tag in tags:
            try:
                versions.append(VersionInfo.from_tag(tag))
            except ValueError:
                continue
        if not versions:
            return None
        return max(versions, key=lambda v: v.as_tuple())

    def detect_from_pyproject(self, path: Path) -> VersionInfo:
        """Read version from a pyproject.toml file."""
        content = path.read_text()
        match = re.search(r'version\s*=\s*"([^"]+)"', content)
        if not match:
            msg = f"No version found in {path}"
            raise ValueError(msg)
        return VersionInfo.from_tag(match.group(1))

"""Validate changelog sections match the required bump type."""

from __future__ import annotations

import re
from pathlib import Path

from pydantic import BaseModel

from cohezion.release.bump_validator import BumpType


# Sections required per bump type (Keep a Changelog format)
# MAJOR uses "any of" logic; MINOR/PATCH use "all of" logic
_REQUIRED_SECTIONS: dict[BumpType, set[str]] = {
    BumpType.MAJOR: {"Changed", "Removed"},
    BumpType.MINOR: {"Added"},
    BumpType.PATCH: {"Fixed"},
    BumpType.NONE: set(),
}

# Bump types where having ANY required section is sufficient (not all)
_ANY_OF_TYPES: set[BumpType] = {BumpType.MAJOR}

_SECTION_PATTERN = re.compile(r"^###\s+(\w+)", re.MULTILINE)


class ChangelogResult(BaseModel):
    """Result of changelog validation."""

    valid: bool
    found_sections: list[str]
    missing_sections: list[str]
    guidance: str | None = None


class ChangelogValidator:
    """Validate changelog has required sections for the proposed bump type."""

    @staticmethod
    def _extract_latest_entry(content: str) -> str:
        """Extract the most recent changelog entry (first ## block)."""
        entries = re.split(r"^## ", content, flags=re.MULTILINE)
        if len(entries) < 2:
            return ""
        return entries[1]

    @staticmethod
    def _extract_sections(entry: str) -> list[str]:
        """Extract ### section names from a changelog entry."""
        return _SECTION_PATTERN.findall(entry)

    @staticmethod
    def validate(content: str, bump_type: BumpType) -> ChangelogResult:
        """Validate changelog content against required sections for bump type."""
        if bump_type == BumpType.NONE:
            return ChangelogResult(valid=True, found_sections=[], missing_sections=[])

        entry = ChangelogValidator._extract_latest_entry(content)
        found = ChangelogValidator._extract_sections(entry)

        required = _REQUIRED_SECTIONS.get(bump_type, set())
        found_required = [s for s in required if s in found]
        missing = [s for s in required if s not in found]

        if not found and bump_type != BumpType.NONE:
            return ChangelogResult(
                valid=False,
                found_sections=[],
                missing_sections=list(required),
                guidance=f"Add a changelog entry with sections: {', '.join(required)}",
            )

        # MAJOR: any one of {Changed, Removed} is sufficient
        if bump_type in _ANY_OF_TYPES:
            if not found_required:
                return ChangelogResult(
                    valid=False,
                    found_sections=found,
                    missing_sections=missing,
                    guidance=f"A {bump_type.name} bump requires at least one of: {', '.join(required)}",
                )
        elif missing:
            return ChangelogResult(
                valid=False,
                found_sections=found,
                missing_sections=missing,
                guidance=f"A {bump_type.name} bump requires these sections: {', '.join(missing)}",
            )

        return ChangelogResult(valid=True, found_sections=found, missing_sections=[])

    @staticmethod
    def validate_file(path: Path, bump_type: BumpType) -> ChangelogResult:
        """Validate a changelog file on disk."""
        if not path.exists():
            msg = f"Changelog not found: {path}"
            raise FileNotFoundError(msg)
        return ChangelogValidator.validate(path.read_text(), bump_type)

"""Version Traceability Gate — story-to-semver contract enforcement.

Links story dependencies to semver contracts, blocks epic completion
on missing traceability, and generates version impact reports.
"""

from __future__ import annotations

from pydantic import BaseModel, Field

from cohezion.release.version_registry import VersionRegistry


class EpicGateResult(BaseModel):
    """Result of epic completion gate check."""

    passed: bool
    missing_stories: list[str] = Field(default_factory=list)
    remediation_steps: list[str] = Field(default_factory=list)


class ImpactReport(BaseModel):
    """Version impact report for a release."""

    version: str
    stories_included: list[str]
    epic_ids: list[str]
    has_breaking_changes: bool
    security_alerts: list[str] = Field(default_factory=list)
    changelog_summary: str = ""


class SecurityIncidentResult(BaseModel):
    """Result of a security incident query."""

    cve_id: str
    affected_versions: list[str] = Field(default_factory=list)
    affected_epics: list[str] = Field(default_factory=list)
    affected_stories: list[str] = Field(default_factory=list)


class TraceabilityGate:
    """Version traceability enforcement for story-to-semver contracts."""

    def __init__(self, registry: VersionRegistry) -> None:
        self._registry = registry
        # In-memory contract store: {story_id: {package: constraint}}
        self._contracts: dict[str, dict[str, str]] = {}
        # story_id → epic_id mapping
        self._story_epic_map: dict[str, str] = {}

    def register_story_contracts(
        self,
        story_id: str,
        epic_id: str,
        dependencies: dict[str, str],
    ) -> None:
        """Register semver contracts for a completed story."""
        self._contracts[story_id] = dict(dependencies)
        self._story_epic_map[story_id] = epic_id

    def get_contracts_for_story(self, story_id: str) -> dict[str, str]:
        """Return contracts registered for a story."""
        return dict(self._contracts.get(story_id, {}))

    def get_contracts_for_epic(self, epic_id: str) -> dict[str, dict[str, str]]:
        """Return all contracts for stories in an epic."""
        result: dict[str, dict[str, str]] = {}
        for story_id, eid in self._story_epic_map.items():
            if eid == epic_id:
                result[story_id] = dict(self._contracts[story_id])
        return result

    def check_epic_completion(
        self,
        epic_id: str,
        completed_stories: list[str],
    ) -> EpicGateResult:
        """Check if all completed stories have version contracts."""
        missing: list[str] = []
        for story_id in completed_stories:
            if story_id not in self._contracts:
                missing.append(story_id)

        if not missing:
            return EpicGateResult(passed=True)

        remediation = [
            f"Register version contracts for story {s} using "
            f"TraceabilityGate.register_story_contracts('{s}', '{epic_id}', {{...}})"
            for s in missing
        ]

        return EpicGateResult(
            passed=False,
            missing_stories=missing,
            remediation_steps=remediation,
        )

    def generate_impact_report(self, version: str) -> ImpactReport | None:
        """Generate a version impact report for a release."""
        entries = self._registry.get_all()
        entry = next((e for e in entries if e.version == version), None)
        if entry is None:
            return None

        has_breaking = entry.bump_type == "MAJOR"

        return ImpactReport(
            version=version,
            stories_included=list(entry.story_ids),
            epic_ids=list(entry.epic_ids),
            has_breaking_changes=has_breaking,
            security_alerts=list(entry.security_alerts),
            changelog_summary=entry.changelog_diff,
        )

    def query_security_incident(self, cve_id: str) -> SecurityIncidentResult:
        """Query for versions affected by a CVE."""
        entries = self._registry.get_all()

        affected_versions: list[str] = []
        affected_epics: set[str] = set()
        affected_stories: set[str] = set()

        for entry in entries:
            if cve_id in entry.security_alerts:
                affected_versions.append(entry.version)
                affected_epics.update(entry.epic_ids)
                affected_stories.update(entry.story_ids)

        return SecurityIncidentResult(
            cve_id=cve_id,
            affected_versions=affected_versions,
            affected_epics=sorted(affected_epics),
            affected_stories=sorted(affected_stories),
        )

