"""Version Telemetry Dashboard — real-time version health monitoring.

Provides version drift detection, coherence scoring, and conflict
detection analogous to HIHO stability in the 12D manifold.
"""

from __future__ import annotations

import re
from typing import Any

from pydantic import BaseModel, Field

from cohezion.release.dependency_scanner import fetch_latest_version


class DriftIndicator(BaseModel):
    """Drift indicator for a single dependency."""

    package_name: str
    current_version: str
    latest_version: str
    severity: str  # "green", "amber", "red"
    recommended_action: str


class VersionConflict(BaseModel):
    """Detected version conflict between requirements."""

    package_name: str
    conflicting_requirements: list[dict[str, str]]


class CoherenceCollapseAlert(BaseModel):
    """Alert triggered when version conflicts cause coherence collapse."""

    package_name: str
    is_collapse: bool
    coherence_value: float
    trigger_healing: bool
    conflicting_requirements: list[dict[str, str]]


class HealthPanel(BaseModel):
    """Version Health panel data for Observatory dashboard."""

    dependencies: dict[str, str]
    drift_indicators: list[DriftIndicator] = Field(default_factory=list)
    coherence_score: float = 1.0


def _parse_version_tuple(version_str: str) -> tuple[int, int, int]:
    """Parse a version string like '2.31.0' into (major, minor, patch)."""
    parts = version_str.split(".")
    try:
        major = int(parts[0]) if len(parts) > 0 else 0
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0
    except ValueError:
        return (0, 0, 0)
    return (major, minor, patch)


def _parse_version_constraint(spec: str) -> list[tuple[str, tuple[int, int, int]]]:
    """Parse a PEP 440 version constraint like '>=1.24,<2.0'."""
    constraints: list[tuple[str, tuple[int, int, int]]] = []
    for part in spec.split(","):
        part = part.strip()
        match = re.match(r"(>=|<=|>|<|==|!=)(\d+(?:\.\d+)*)", part)
        if match:
            op = match.group(1)
            ver = _parse_version_tuple(match.group(2))
            constraints.append((op, ver))
    return constraints


def _constraints_overlap(
    constraints_a: list[tuple[str, tuple[int, int, int]]],
    constraints_b: list[tuple[str, tuple[int, int, int]]],
) -> bool:
    """Check if two sets of version constraints can be simultaneously satisfied."""
    lower_a = _get_lower_bound(constraints_a)
    upper_a = _get_upper_bound(constraints_a)
    lower_b = _get_lower_bound(constraints_b)
    upper_b = _get_upper_bound(constraints_b)

    effective_lower = max(lower_a, lower_b)
    effective_upper = min(upper_a, upper_b)

    return effective_lower < effective_upper


def _get_lower_bound(
    constraints: list[tuple[str, tuple[int, int, int]]],
) -> tuple[int, int, int]:
    """Get the effective lower bound from constraints."""
    lower = (0, 0, 0)
    for op, ver in constraints:
        if op in (">=", ">"):
            if ver > lower:
                lower = ver
    return lower


def _get_upper_bound(
    constraints: list[tuple[str, tuple[int, int, int]]],
) -> tuple[int, int, int]:
    """Get the effective upper bound from constraints."""
    upper = (999, 999, 999)
    for op, ver in constraints:
        if op in ("<=", "<"):
            if ver < upper:
                upper = ver
    return upper


class VersionTelemetry:
    """Version telemetry with drift detection and coherence scoring."""

    def __init__(self, drift_threshold_minor: int = 2) -> None:
        self._threshold = drift_threshold_minor

    def get_health_panel(self, dependencies: dict[str, str]) -> HealthPanel:
        """Build health panel with versions, drift indicators, and coherence."""
        drift_indicators: list[DriftIndicator] = []

        for pkg, current_ver in dependencies.items():
            latest = fetch_latest_version(pkg)
            if latest is None or latest == current_ver:
                continue

            current = _parse_version_tuple(current_ver)
            latest_t = _parse_version_tuple(latest)

            severity = self._classify_drift(current, latest_t)
            if severity == "green":
                continue

            action = f"Upgrade {pkg} from {current_ver} to {latest}"
            drift_indicators.append(
                DriftIndicator(
                    package_name=pkg,
                    current_version=current_ver,
                    latest_version=latest,
                    severity=severity,
                    recommended_action=action,
                )
            )

        coherence = self._calculate_coherence(drift_indicators, len(dependencies))

        return HealthPanel(
            dependencies=dict(dependencies),
            drift_indicators=drift_indicators,
            coherence_score=coherence,
        )

    def detect_conflicts(self, requirements: list[dict[str, Any]]) -> list[VersionConflict]:
        """Detect version conflicts between requirements."""
        by_package: dict[str, list[dict[str, str]]] = {}
        for req in requirements:
            pkg = req["package"]
            entry = {
                "requires": req["requires"],
                "required_by": req["required_by"],
            }
            by_package.setdefault(pkg, []).append(entry)

        conflicts: list[VersionConflict] = []
        for pkg, reqs in by_package.items():
            if len(reqs) < 2:
                continue

            # Check pairwise compatibility
            all_constraints = [_parse_version_constraint(r["requires"]) for r in reqs]
            for i in range(len(all_constraints)):
                for j in range(i + 1, len(all_constraints)):
                    if not _constraints_overlap(all_constraints[i], all_constraints[j]):
                        conflicts.append(
                            VersionConflict(
                                package_name=pkg,
                                conflicting_requirements=reqs,
                            )
                        )
                        break
                else:
                    continue
                break

        return conflicts

    def check_coherence_collapse(self, requirements: list[dict[str, Any]]) -> list[CoherenceCollapseAlert]:
        """Check for coherence collapse (analogous to HIHO < 0.3)."""
        conflicts = self.detect_conflicts(requirements)
        alerts: list[CoherenceCollapseAlert] = []

        for conflict in conflicts:
            alerts.append(
                CoherenceCollapseAlert(
                    package_name=conflict.package_name,
                    is_collapse=True,
                    coherence_value=0.1,
                    trigger_healing=True,
                    conflicting_requirements=conflict.conflicting_requirements,
                )
            )

        return alerts

    def _classify_drift(
        self,
        current: tuple[int, int, int],
        latest: tuple[int, int, int],
    ) -> str:
        """Classify drift severity: green, amber, or red."""
        if latest[0] > current[0]:
            return "red"

        minor_diff = latest[1] - current[1]
        if minor_diff >= self._threshold:
            return "amber"

        return "green"

    def _calculate_coherence(self, drift_indicators: list[DriftIndicator], total_deps: int) -> float:
        """Calculate coherence score from drift indicators."""
        if total_deps == 0:
            return 1.0

        penalty = 0.0
        for d in drift_indicators:
            if d.severity == "red":
                penalty += 0.3
            elif d.severity == "amber":
                penalty += 0.15

        score = max(0.0, 1.0 - penalty)
        return round(score, 2)

